import{_ as e,o as a,c as i,ag as r}from"./chunks/framework.CKjyCoVi.js";const b=JSON.parse('{"title":"关于 Skill Hub","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),t={name:"about.md"};function o(s,l,n,u,h,c){return a(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="关于-skill-hub" tabindex="-1">关于 Skill Hub <a class="header-anchor" href="#关于-skill-hub" aria-label="Permalink to &quot;关于 Skill Hub&quot;">​</a></h1><h2 id="🎯-项目简介" tabindex="-1">🎯 项目简介 <a class="header-anchor" href="#🎯-项目简介" aria-label="Permalink to &quot;🎯 项目简介&quot;">​</a></h2><p><strong>Skill Hub</strong> 是一个自动化的 OpenClaw 和 MCP (Model Context Protocol) 技能收集与展示平台。</p><p>我们的目标是帮助开发者：</p><ul><li>🔍 <strong>发现</strong> 最新、最热门的 AI 能力插件</li><li>📊 <strong>了解</strong> Skills 的热度和活跃度</li><li>⚡ <strong>快速</strong> 找到满足需求的工具</li><li>🌐 <strong>集成</strong> 多个来源的数据</li></ul><h2 id="🤖-工作原理" tabindex="-1">🤖 工作原理 <a class="header-anchor" href="#🤖-工作原理" aria-label="Permalink to &quot;🤖 工作原理&quot;">​</a></h2><h3 id="自动爬取" tabindex="-1">自动爬取 <a class="header-anchor" href="#自动爬取" aria-label="Permalink to &quot;自动爬取&quot;">​</a></h3><p>每天通过 GitHub Actions 自动运行爬虫脚本，从以下来源收集数据：</p><ol><li><p><strong>GitHub</strong></p><ul><li>Topic 搜索: <code>mcp-server</code>, <code>openclaw-skill</code>, <code>model-context-protocol</code></li><li>关键词搜索: <code>mcp server</code>, <code>SKILL.md</code></li><li>获取仓库元数据、README、Star 数等</li></ul></li><li><p><strong>NPM Registry</strong></p><ul><li>搜索包含 MCP 相关关键词的包</li><li>获取包的描述、版本、发布时间等</li></ul></li></ol><h3 id="智能分类" tabindex="-1">智能分类 <a class="header-anchor" href="#智能分类" aria-label="Permalink to &quot;智能分类&quot;">​</a></h3><p>根据名称、描述、Topics 等信息，自动将 Skills 分类为：</p><ul><li>Development (开发工具)</li><li>Productivity (效率工具)</li><li>Data (数据相关)</li><li>AI (人工智能)</li><li>Utility (实用工具)</li><li>Integration (集成服务)</li><li>Other (其他)</li></ul><h3 id="数据展示" tabindex="-1">数据展示 <a class="header-anchor" href="#数据展示" aria-label="Permalink to &quot;数据展示&quot;">​</a></h3><ul><li><strong>技能列表</strong>: 完整的 Skills 清单，支持搜索和过滤</li><li><strong>分类浏览</strong>: 按功能分类展示</li><li><strong>趋势榜</strong>: 最受欢迎和最近更新的 Skills</li></ul><h2 id="📊-数据更新" tabindex="-1">📊 数据更新 <a class="header-anchor" href="#📊-数据更新" aria-label="Permalink to &quot;📊 数据更新&quot;">​</a></h2><ul><li><strong>频率</strong>: 每天自动更新一次</li><li><strong>时间</strong>: 北京时间每天凌晨 2:00</li><li><strong>方式</strong>: GitHub Actions 自动运行爬虫脚本</li><li><strong>部署</strong>: 更新后自动重新部署网站</li></ul><h2 id="🛠️-技术栈" tabindex="-1">🛠️ 技术栈 <a class="header-anchor" href="#🛠️-技术栈" aria-label="Permalink to &quot;🛠️ 技术栈&quot;">​</a></h2><ul><li><strong>前端</strong>: VitePress (Vue 3)</li><li><strong>爬虫</strong>: Node.js (Axios + Cheerio)</li><li><strong>数据存储</strong>: JSON 文件</li><li><strong>自动化</strong>: GitHub Actions</li><li><strong>部署</strong>: GitHub Pages / Vercel / Netlify</li></ul><h2 id="📝-数据来源" tabindex="-1">📝 数据来源 <a class="header-anchor" href="#📝-数据来源" aria-label="Permalink to &quot;📝 数据来源&quot;">​</a></h2><p>所有数据来自公开的 API 和仓库：</p><ul><li>GitHub API</li><li>NPM Registry API</li><li>各项目的公开 README 和元数据</li></ul><h2 id="🤝-贡献" tabindex="-1">🤝 贡献 <a class="header-anchor" href="#🤝-贡献" aria-label="Permalink to &quot;🤝 贡献&quot;">​</a></h2><p>欢迎参与贡献！</p><h3 id="提交新-skill" tabindex="-1">提交新 Skill <a class="header-anchor" href="#提交新-skill" aria-label="Permalink to &quot;提交新 Skill&quot;">​</a></h3><p>如果您发现了优秀的 Skill 但平台未收录，请：</p><ol><li>在 GitHub 上为 Skill 添加 Topic: <code>mcp-server</code> 或 <code>openclaw-skill</code></li><li>或者直接提交 Issue 告诉我们</li></ol><h3 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h3><p>发现数据错误或网站 Bug？</p><ul><li><a href="https://github.com/yourusername/skill-hub/issues" target="_blank" rel="noreferrer">提交 Issue</a></li></ul><h3 id="改进爬虫" tabindex="-1">改进爬虫 <a class="header-anchor" href="#改进爬虫" aria-label="Permalink to &quot;改进爬虫&quot;">​</a></h3><p>想帮助改进爬虫逻辑或添加新的数据源？</p><ul><li><a href="https://github.com/yourusername/skill-hub/pulls" target="_blank" rel="noreferrer">提交 Pull Request</a></li></ul><h2 id="⚖️-免责声明" tabindex="-1">⚖️ 免责声明 <a class="header-anchor" href="#⚖️-免责声明" aria-label="Permalink to &quot;⚖️ 免责声明&quot;">​</a></h2><ul><li>本平台仅收集和展示公开信息</li><li>我们不对 Skills 的质量、安全性或可用性负责</li><li>使用任何 Skill 前，请自行评估和测试</li><li>Star 数等指标仅供参考，不代表质量保证</li></ul><h2 id="📧-联系方式" tabindex="-1">📧 联系方式 <a class="header-anchor" href="#📧-联系方式" aria-label="Permalink to &quot;📧 联系方式&quot;">​</a></h2><ul><li>GitHub: <a href="https://github.com/yourusername" target="_blank" rel="noreferrer">@yourusername</a></li><li>Email: <a href="mailto:your.email@example.com" target="_blank" rel="noreferrer">your.email@example.com</a></li><li>Issues: <a href="https://github.com/yourusername/skill-hub/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li></ul><h2 id="📄-开源协议" tabindex="-1">📄 开源协议 <a class="header-anchor" href="#📄-开源协议" aria-label="Permalink to &quot;📄 开源协议&quot;">​</a></h2><p>MIT License - 自由使用、修改和分发</p><hr><p><strong>Powered by</strong>: VitePress + GitHub Actions + ❤️</p>',40)])])}const g=e(t,[["render",o]]);export{b as __pageData,g as default};
